			sse({ type: "content_block_stop", index: 1 }) +
			sse({ type: "message_delta", usage: { output_tokens: 42 } });
		const out = rewriter.push(input.slice(0, 50)) + rewriter.push(input.slice(50)) + rewriter.flush();
